let battleView=false;
function campStatus(camp=s.camp){let alive=camp.enemies.filter(e=>e.hp>0);return camp.defeated?'База захвачена. Земля вокруг неё ваша — можно строить.':camp.name+' · '+['','Слабая','Средняя','Сильная'][camp.tier]+' · защитников: '+alive.length+' ('+alive.filter(e=>e.type==='archer').length+' лучн.). '+(camp.engaged?'Идёт бой.':'')}
function showCamp(){let c=s.camp;openSheet(c.name,'ВРАЖЕСКАЯ БАЗА',`<div class="info-box" data-camp-status>${campStatus()}</div><button class="gold wide" data-combat="attack" ${c.defeated?'disabled':''}>Атаковать · ${armyFilterLabel()}</button><button class="secondary" data-combat="watch">Смотреть базу</button><button class="secondary" data-combat="retreat">Отступить и лечиться</button><div class="info-box">Добыча: ${60*c.tier} дерева · ${30*c.tier} камня · ${6*c.tier} готового мяса · ${4*c.tier} руды. Награда один раз.</div><p>Лес закрывает линию огня. Для перехода реки нужен мост. Раненые возвращаются в казармы; лечение расходует приготовленную еду.</p><button class="secondary" data-combat="bases">Все базы</button>`,'camp')}
function combatClick(b){if(b.dataset.base){Combat.select(s,b.dataset.base);showCamp();return true}if(!b.dataset.combat)return false;let action=b.dataset.combat;if(action==='orders'){closeSheet();toggleArmy();return true}if(action==='bases'){showBases();return true}if(action==='camp'){showCamp();return true}if(action==='watch'){if(!Combat.discovered(s)){toast('Сначала разведайте базу');return true}battleView=!battleView;closeSheet();toast(battleView?'Камера у базы. Кнопка «Домой» вернёт к персонажу.':'Камера следует за вами');return true}let result=action==='attack'?Combat.attack(s,s.camp.id,armyFilter):Combat.retreat(s,armyFilter);economyResult(result);if(!result.error)closeSheet();return true}
function battleLabel(u){return `${Math.ceil(u.hp)} / ${u.maxHp} здоровья · ${u.hp<=0?'Тяжело ранен':u.returning?u.status||'Возвращается':u.battle?'В бою':u.wounded?'Нужно лечение':u.order==='follow'?'Сопровождает':u.route.length?'Идёт на позицию':'Охраняет позицию'}`}
function renderCombatStatus(){for(let el of document.querySelectorAll('[data-army-summary]'))el.textContent=s.soldiers.length+' / '+Military.capacity(s)+' воинов · обучаются '+Military.queued(s);for(let el of document.querySelectorAll('[data-army-count]'))el.textContent=s.soldiers.filter(u=>u.type===el.dataset.armyCount).length;for(let el of document.querySelectorAll('[data-camp-status]'))el.textContent=campStatus();for(let el of document.querySelectorAll('[data-soldier-status]')){let u=s.soldiers.find(u=>u.id===el.dataset.soldierStatus);if(u)el.textContent=battleLabel(u)}let quick=$('#armyQuick');if(quick){quick.hidden=false;quick.textContent='Войска · '+s.soldiers.filter(u=>!u.wounded&&u.hp>0).length}let raid=s.war.raid,alert=$('#raidAlert');if(alert){alert.hidden=!raid;if(raid){let source=s.camps.find(c=>c.id===raid.source);$('#raidText').textContent=raid.phase==='warning'?'Набег: '+(source?.name||'враги')+' · выход через '+fmt(raid.remaining):raid.phase==='retreating'?'Противник отступает':'Враги идут к поселению';}}}
function drawHealth(u,enemy=false){if(!s.camp.engaged&&u.hp>=u.maxHp&&!u.returning)return;let x=u.x*C.T,y=u.y*C.T;ctx.fillStyle='#19282c';ctx.fillRect(x-16,y-35,32,5);ctx.fillStyle=enemy?'#d87465':u.hp<u.maxHp*.3?'#e2b675':'#9dcb83';ctx.fillRect(x-15,y-34,30*Math.max(0,u.hp)/u.maxHp,3);if(u.hitUntil>s.time)sprite('Particle FX/Dust_01.png',x-32,y-48,64,64,(.18-u.hitUntil+s.time)*40,64);if(u.healing){ctx.fillStyle='#b7e5a0';ctx.fillRect(x-1,y-43,3,9);ctx.fillRect(x-4,y-40,9,3)}}
function drawEnemy(u){let x=u.x*C.T,y=u.y*C.T,kind=u.type==='archer'?'Archer':'Warrior',state=u.attackUntil>s.time?(u.type==='archer'?'Shoot':'Attack1'):u.moving?'Run':'Idle';shadow(x,y+4,12);if(u.hp<=0){ctx.save();ctx.globalAlpha=.5;ctx.translate(x,y);ctx.rotate(-Math.PI/2);sprite(`Units/${u.color||'Red'} Units/${kind}/${kind}_Idle.png`,-40,-40,80,80,0,192);ctx.restore();return}sprite(`Units/${u.color||'Red'} Units/${kind}/${kind}_${state}.png`,x-48,y-64,96,96,anim*(u.moving||u.attackUntil>s.time?9:4),192,u.face<0);drawHealth(u,true)}
function drawCamp(c=s.camp){if(c.defeated)return;for(let b of c.structures||[])drawEnemyBuilding(c,b)}
function drawEnemyBuilding(c,b){let r=C.recipes[b.type],x=b.x*C.T,y=b.y*C.T;if(b.type==='fence'||b.type==='gate'){for(let dx of b.type==='fence'?[0,14,28]:[0,32])sprite(STUMP,x+dx-8,y-15,32,43)}else if(b.type==='tower')sprite('Buildings/'+(c.color||'Red')+' Buildings/Tower.png',x-20,y-80,88,176);else{let w=b.type==='barracks'?128:112,h=b.type==='barracks'?w*256/192:w*1.5;sprite('Buildings/'+(c.color||'Red')+' Buildings/'+b.art+'.png',x+(r.w*C.T-w)/2,y+r.h*C.T-h,w,h)}}
function drawArrows(){for(let a of s.combatShots){if(!explored.has(Math.floor(a.x)+','+Math.floor(a.y)))continue;ctx.save();ctx.translate(a.x*C.T,a.y*C.T-15);ctx.rotate(Math.atan2(a.ty-a.fromY,a.tx-a.fromX));sprite('Units/'+(a.enemy?(a.color||'Red'):'Blue')+' Units/Archer/Arrow.png',-24,-24,48,48);ctx.restore()}}
function drawCampfire(b){let x=(b.x+.5)*C.T,y=(b.y+.5)*C.T;sprite('Terrain/Resources/Wood/Wood Resource/Wood Resource.png',x-24,y-13,48,48);for(let n of ['01','02','03'])sprite('Particle FX/Fire_'+n+'.png',x-32,y-42,64,64,anim*9,64)}

let armyFilter='all',armyAttackMode=false;
function armyFilterLabel(){return armyFilter==='fighter'?'бойцы':armyFilter==='archer'?'лучники':'весь отряд'}
function showBases(){openSheet('Вражеские базы','РАЗВЕДКА · '+s.camps.length+' БАЗ',s.camps.map(c=>Combat.discovered(s,c)?`<button class="base-row" data-base="${c.id}"><b>${c.name}</b><small>${campStatus(c)}</small></button>`:`<div class="base-row unexplored"><b>Неизвестная база</b><small>${c.x<s.claim.x?'Запад':c.x>s.claim.x+s.claim.w?'Восток':'Центр'} · ${c.y<s.claim.y?'север долины':'юг долины'}. Нужна разведка.</small></div>`).join('')+'<p>Первый набег — через 10 минут активной игры с армией. Предупреждение за 75 секунд до выхода. Между набегами не меньше 8 минут. Каждые 5 вышедших набегов противник усиливается. Численность учитывает здоровую армию и башни. Налётчики отступают после потерь, когда в отряде остаётся не больше 2–3 бойцов. Пока игра закрыта, враги не нападают.</p>','bases')}
function toggleArmy(){workerFocus=null;if(placement)cancelPlacement();let bar=$('#armyBar');bar.hidden=!bar.hidden;armyPlacement=false;armyAttackMode=false;audio.play('click')}
function quickOrder(action){if(action==='defend'&&!$('#sheet').hidden)closeSheet();if(action==='bases'){showBases();return}if(action==='manage'){showArmy();return}if(action==='cancel'){armyPlacement=false;armyAttackMode=false;$('#orderHint').hidden=true;return}if(!s.soldiers.some(u=>u.hp>0&&!u.wounded&&(action==='defend'||armyFilter==='all'||u.type===armyFilter))){toast('В этой группе нет здоровых воинов');return}if(action==='attack'||action==='position'){armyAttackMode=action==='attack';armyPlacement=action==='position';$('#armyBar').hidden=true;$('#orderHint').hidden=false;$('#orderText').textContent=armyAttackMode?'Выберите вражескую базу или отряд':'Выберите место обороны';toast($('#orderText').textContent);return}let result=action==='defend'?Combat.defend(s):Combat.command(s,action==='follow'?'follow':'retreat',null,armyFilter);economyResult(result);if(!result.error){$('#armyBar').hidden=true;armyPlacement=false;armyAttackMode=false;$('#orderHint').hidden=true}}
function armyMapClick(x,y){if(!armyAttackMode&&!armyPlacement)return false;if(!explored.has(x+','+y)){toast('Сначала разведайте этот участок');return true}let result;if(armyAttackMode){let c=s.camps.find(c=>Math.abs(c.x-x)<=3&&Math.abs(c.y-y)<=3&&!c.defeated),e=Combat.enemies(s).find(e=>e.hp>0&&Math.hypot(e.x-x-.5,e.y-y-.5)<1.5);if(!c&&e)c=s.camps.find(c=>c.enemies.includes(e));result=c?Combat.attack(s,c.id,armyFilter):e?Combat.command(s,'guard',{x:x+.5,y:y+.5},armyFilter):{error:'Нажмите на вражескую базу или отряд'};}else result=Combat.command(s,'guard',{x:x+.5,y:y+.5},armyFilter);if(economyResult(result)){armyAttackMode=false;armyPlacement=false;$('#orderHint').hidden=true}return true}
function initWarControls(){ $('#armyBar').onclick=e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.filter){armyFilter=b.dataset.filter;for(let button of document.querySelectorAll('[data-filter]'))button.setAttribute('aria-pressed',String(button.dataset.filter===armyFilter));audio.play('click')}else if(b.dataset.quick)quickOrder(b.dataset.quick)};$('#defendNow').onclick=()=>quickOrder('defend');$('#cancelOrder').onclick=()=>quickOrder('cancel');}



function drawRuins(b){let r=C.recipes[b.type],x=b.x*C.T,y=b.y*C.T;for(let yy=0;yy<r.h;yy++)for(let xx=0;xx<r.w;xx++){sprite(ROCK,x+xx*C.T-5,y+yy*C.T+3,42,42);sprite('Terrain/Resources/Wood/Wood Resource/Wood Resource.png',x+xx*C.T+8,y+yy*C.T+8,40,40)}if(s.time-(b.ruinedAt||0)<1)sprite('Particle FX/Explosion_02.png',x-16,y-32,96,96,(s.time-b.ruinedAt)*9,192)}
function drawStructureDamage(b){if(b.hp>=b.maxHp&&!b.repair)return;let r=C.recipes[b.type],x=(b.x+r.w/2)*C.T,y=(b.y+r.h/2)*C.T;if(!b.repair){for(let i=0;i<(b.ruined?1:2);i++){let phase=(anim*5+i*4)%8;ctx.save();ctx.globalAlpha=b.ruined?.4:.55;sprite('Particle FX/Dust_02.png',x-32+i*18,y-48-phase*3,64,64,phase,64);ctx.restore()}if(b.burningUntil>s.time)for(let i=0;i<Math.max(1,r.w);i++)for(let n of ['01','02','03'])sprite('Particle FX/Fire_'+n+'.png',b.x*C.T+i*32-4,y-34,72,72,anim*9+i*3,64)}ctx.fillStyle='#18352a';ctx.fillRect(x-25,b.y*C.T-20,50,6);ctx.fillStyle=b.ruined?'#ad7c64':b.hp<b.maxHp*.4?'#e7996e':'#c6d890';ctx.fillRect(x-24,b.y*C.T-19,48*b.hp/b.maxHp,4);if(b.repair){ctx.fillStyle='#a9cfdf';ctx.fillRect(x-24,b.y*C.T-11,48*(1-b.repair.remaining/b.repair.duration),3)}}



